 insert into public.flashcards(set_id,front,back,sort_order) select '6da7364a-3c81-4086-8889-aad04e614628',v.front,v.back,v.position from (values
($pilot$Why use a buffer between components with different transfer rates?$pilot$,$pilot$It temporarily queues data during transfer so the faster component can continue while the slower one processes it; it is not permanent storage.$pilot$,10),
($pilot$Compare SRAM and DRAM refresh, speed and typical use.$pilot$,$pilot$Both are volatile. SRAM is faster and needs no periodic refresh while powered, so it suits cache; DRAM needs refresh but is denser and cheaper per bit, so it suits main memory.$pilot$,11),
($pilot$How do PROM, EPROM and EEPROM differ?$pilot$,$pilot$PROM is programmed once; EPROM is erased with ultraviolet light and programmed again; EEPROM is erased electrically and reprogrammed, often in-circuit.$pilot$,12),
($pilot$Give one benefit and one limitation of an embedded system.$pilot$,$pilot$A dedicated embedded computer can be compact, low-power and reliable for its task; it may be difficult to upgrade or repair and has limited flexibility.$pilot$,13),
($pilot$How does monitoring differ from control?$pilot$,$pilot$Monitoring records, displays or reports sensor readings; control uses measured input to decide an action and can operate an actuator.$pilot$,14),
($pilot$What makes a control system closed-loop?$pilot$,$pilot$It measures the result of an action and feeds that reading back to the controller, which can adjust later actions against a target.$pilot$,15),
($pilot$State the functions of NAND and NOR.$pilot$,$pilot$NAND = NOT(A AND B), so it is 0 only when both inputs are 1. NOR = NOT(A OR B), so it is 1 only when both inputs are 0.$pilot$,16),
($pilot$When does XOR output 1?$pilot$,$pilot$For two inputs, XOR outputs 1 when exactly one input is 1; equivalently, when inputs differ. It outputs 0 when they match.$pilot$,17),
($pilot$State De Morgan's two laws.$pilot$,$pilot$(A AND B)' = A' OR B'; (A OR B)' = A' AND B'. Complement each input and swap AND with OR.$pilot$,18),
($pilot$What are the Sum and Carry outputs of a half adder?$pilot$,$pilot$Sum = A XOR B; Carry = A AND B. A half adder has no carry-in input.$pilot$,19),
($pilot$What are the Sum and Carry-out expressions of a full adder?$pilot$,$pilot$Sum = A XOR B XOR Cin. Cout = AB + A·Cin + B·Cin; carry is produced when at least two inputs are 1.$pilot$,20),
($pilot$What grouping rules matter in a Karnaugh map?$pilot$,$pilot$Use Gray-code labels; group adjacent 1s in rectangles of 1, 2, 4, 8... cells. Opposite edges wrap; diagonals are not adjacent. Eliminate variables that change within a group.$pilot$,21)
 ) as v(front,back,position);
